pub fn handle(args: ReleaseCommandArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    match args.command {
        None => release(&args.packages, args.receipt.as_deref(), global),
        Some(ReleaseArgs::Pending(args)) => pending(args, global),
