/// Stderr note when a preview's tags have no `origin` to push to.
pub const TAGS_UNBOUND_NOTE: &str =
    "note: `origin` is missing or not a hosted remote, so tag operations are unbound; a real `callisto release` needs a hosted remote";

/// Stderr note when `callisto version` has work for the selection: a release plans only versions already written.
fn pending_version_note(packages: &[callisto_model::ReleasePackageId]) -> String {
    let names = packages
        .iter()
        .map(|package| format!("`{package}`"))
        .collect::<Vec<_>>();
    format!(
        "note: pending version work for {} is not in this plan: run `callisto version` (or merge the release PR) first",
        names.join(", ")
    )
}

/// Stderr warning for a tag that exists here but not on `origin`.
fn tag_missing_from_origin_note(tag: &str) -> String {
    format!(
        "warning: tag `{tag}` exists here but not on `origin`, so its release may not have finished: check out the \
         tagged commit and run `callisto release` again, or push the tag if the release is complete"
    )
}

/// Exact stdout when no package has an unreleased version.
pub const NOTHING_TO_RELEASE: &str = "Nothing to release.";

fn release(packages: &[String], receipt: Option<&std::path::Path>, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let selections = parse_selections(packages)?;
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let root = workspace.root.clone();
    let locator = IgnoreWalkLocator::new(&root);
    if let Some(route) = ci_release_route(&workspace)?.filter(|_| !global.dry_run) {
        return Err(CliError::ReleaseRequiresCiRoute {
            reason: route.to_string(),
        });
    }
    let mode = if global.dry_run {
        LocalReleaseSource::Preview
    } else {
        LocalReleaseSource::Trusted
    };
    // The one `ls-remote` is network latency; it runs beside the plan rather than before it. Best effort: a tag that
    // never reached `origin` is a release that did not finish, whatever the plan says next.
    let probe = origin_tag_probe(&workspace).ok().flatten();
    let (missing, planned) = std::thread::scope(|scope| {
        let missing = probe.as_ref().map(|probe| scope.spawn(|| probe.missing(&runner)));
        let planned = plan_loaded_release(&workspace, &selections, mode);
        (missing.map(|handle| handle.join().unwrap_or_default()), planned)
    });
    for tag in missing.unwrap_or_default() {
        eprintln!("{}", tag_missing_from_origin_note(&tag));
    }
    let plan = planned?;
    if global.dry_run {
        // Advisory: a plan `version` cannot derive is that command's error to report.
        let pending = pending_version_work(&workspace, &selections).unwrap_or_default();
        write_release_preview(plan.as_ref(), &pending, global.format, &mut std::io::stdout())?;

/// Derives a durable decision for explicit, exact release identities.
///
/// A linked group is one release unit: selecting any member includes every
/// member of that linked group which the version plan selected. All other
/// packages remain outside the authority boundary. The caller must pass
/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
/// for release authority.
pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    let owners = ReleaseOwners::of(workspace);
    let released = complete
        .entries
        .iter()
        .map(|entry| &entry.package)
        .collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = owners.get(selection) else {
            let missing = callisto_model::PackageId::Prefixed {
                ecosystem: selection.ecosystem(),
                name: selection.name().to_string(),
            };
            return Err(GraphError::unknown_package(
                missing,
                workspace.graph.packages().map(Package::canonical_id),
            ));
        };
        let reason = if !released.contains(*selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if !package.is_release_point() {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, &owners, complete.entries, &selected);
    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
}
